INSERT INTO repo_cf_knowledge (cf_knowledge_id, education_level, sub_heading, text, status) VALUES ('CFK_SDG15_ADULT_002', 'Adult education', 'Environmental economics and market opportunities', 'Market-based solutions, such as eco-labelling, and government incentives promote sustainable agriculture, forest conservation, and renewable energy.', 'Active'), ('CFK_SDG15_ADULT_003', 'Adult education', 'Environmental economics and market opportunities', 'Sustainable practices, including carbon credits, payments for ecosystem services, and resilient land management, provide long-term economic benefits.', 'Active'), ('CFK_SDG15_ADULT_004', 'Adult education', 'Importance of healthy ecosystems', 'Forests, wetlands, grasslands, and other ecosystems sustain biodiversity and human wellbeing.', 'Active'), ('CFK_SDG15_ADULT_005', 'Adult education', 'Importance of healthy ecosystems', 'Ecosystems provide essential services: clean air and water, fertile soil, climate regulation, and cultural value.', 'Active'), ('CFK_SDG15_ADULT_006', 'Adult education', 'Importance of healthy ecosystems', 'Deforestation, desertification, and biodiversity loss result from unsustainable practices.', 'Active'), ('CFK_SDG15_ADULT_007', 'Adult education', 'Importance of healthy ecosystems', 'Sustainable land and ecosystem management enhances resilience to climate change and natural disasters.', 'Active'), ('CFK_SDG15_ADULT_008', 'Adult education', 'Poaching and wildlife trafficking', 'Poaching and illegal wildlife trade harm biodiversity, ecosystems, and communities.', 'Active'), ('CFK_SDG15_ADULT_009', 'Adult education', 'Poaching and wildlife trafficking', 'Legal frameworks and international agreements, such as CITES, guide species protection.', 'Active'), ('CFK_SDG15_ADULT_010', 'Adult education', 'Poaching and wildlife trafficking', 'Enforcement agencies, conservation organisations, and local communities prevent wildlife crime.', 'Active'), ('CFK_SDG15_ADULT_011', 'Adult education', 'Poaching and wildlife trafficking', 'Poverty, limited livelihoods, and market demand drive poaching and trafficking.', 'Active'), ('CFK_SDG15_ADULT_012', 'Adult education', 'Poaching and wildlife trafficking', 'Community-based conservation and alternative livelihoods reduce illegal activities.', 'Active'), ('CFK_SDG15_ADULT_013', 'Adult education', 'Land tenure and traditional rights', 'Land tenure systems shape sustainable land management and resource access.', 'Active'), ('CFK_SDG15_ADULT_014', 'Adult education', 'Land tenure and traditional rights', 'Securing land rights for indigenous peoples, local communities, and small-scale farmers promotes equity.', 'Active'), ('CFK_SDG15_ADULT_015', 'Adult education', 'Land tenure and traditional rights', 'Customary and traditional practices support ecosystem conservation.', 'Active'), ('CFK_SDG15_ADULT_016', 'Adult education', 'Land tenure and traditional rights', 'Participatory governance and legal frameworks protect community and indigenous land rights.', 'Active'), ('CFK_SDG15_ADULT_017', 'Adult education', 'Community-led conservation and sustainable practices', 'Community-based conservation empowers local populations to manage natural resources sustainably.', 'Active'), ('CFK_SDG15_ADULT_018', 'Adult education', 'Community-led conservation and sustainable practices', 'Practices such as agroforestry, sustainable agriculture, and water conservation restore degraded land.', 'Active'), ('CFK_SDG15_ADULT_019', 'Adult education', 'Community-led conservation and sustainable practices', 'Traditional ecological knowledge (TEK) complements scientific approaches in land management.', 'Active'), ('CFK_SDG15_ADULT_020', 'Adult education', 'Community-led conservation and sustainable practices', 'Nature-based solutions restore ecosystems while creating economic opportunities.', 'Active'), ('CFK_SDG15_ADULT_021', 'Adult education', 'Market-based solutions for sustainability', 'Environmental economics strategies, including eco-labelling, sustainable 